package server

import (
	"fmt"
	"net/http"
	"strings"
)

// CLI token refresh uses default_client headers, while authorization-code
// exchange uses create_raw_auth_client. Neither carries the model provider's
// Version header. These requests are generated by the gateway, not copied
// from an inference client, and must not acquire its bearer/session identity.
func applyGatewayOAuthHeaders(headers http.Header, settings Settings, rawAuth bool) error {
	if headers == nil {
		return fmt.Errorf("%w: OAuth request requires writable headers", errInvalid)
	}
	for name := range headers {
		switch strings.ToLower(name) {
		case "user-agent", "originator", "version", "authorization", "chatgpt-account-id", "x-oai-attestation":
			delete(headers, name)
		}
	}
	if rawAuth {
		// A present key with zero values suppresses Go's automatic UA without
		// emitting an empty header through the native IPC header serializer.
		headers["User-Agent"] = nil
		return nil
	}
	// Use the verified local CLI capture for gateway-generated requests only.
	// Without a configured capture, retain the explicit short compatibility UA.
	userAgent, originator := gatewayDefaultApplicationIdentity()
	headers.Set("User-Agent", userAgent)
	headers.Set("Originator", originator)
	if err := applyCodexFingerprint(headers, settings); err != nil {
		return err
	}
	headers.Del("Version")
	return nil
}
